def strip_latest_stories_heading_from_homepage(apps, schema_editor):
    """Remove seeded H2 + optional intro paragraph from HomePage StreamField bodies."""
    from home.models import HomePage

    seed_intro = "Highlights from recently published articles across the site."

    for page in HomePage.objects.all().iterator():
        blocks = list(page.body)
        if not blocks:
            continue
        new_blocks = []
        i = 0
        changed = False
        while i < len(blocks):
            b = blocks[i]
            if b.block_type == "heading" and (b.value.get("text") or "").strip() == "Latest stories":
                changed = True
                i += 1
                if i < len(blocks) and blocks[i].block_type == "paragraph":
                    pv = blocks[i].value
                    src = getattr(pv, "source", str(pv or ""))
                    if seed_intro in src:
                        changed = True
                        i += 1
                continue
            new_blocks.append((b.block_type, b.value))
            i += 1
        if changed:
            page.body = new_blocks
            revision = page.save_revision()
            revision.publish()


